787: export function triggerWildEncounter(poolOrEntry, trainerMeta = null) {
788:   let level = 5;
789:   let species = "PIDGEY";
790:   if (Array.isArray(poolOrEntry) && Array.isArray(poolOrEntry[0])) {
791:     // Gen 1 slot weights: 20%, 20%, 15%, 10%, 10%, 10%, 5%, 5%, 4%, 1%
792:     const pick = poolOrEntry[Math.floor(Math.random() * poolOrEntry.length)];
793:     level = pick[0];
794:     species = pick[1];
795:   } else if (Array.isArray(poolOrEntry)) {
796:     level = poolOrEntry[0];
797:     species = poolOrEntry[1];
798:   }
799:   const maxHp = 14 + level * 3;
800:   const trainerName = trainerMeta?.trainerName || null;
801:   state.battle = {
802:     species,
803:     level,
804:     hp: maxHp,
805:     maxHp,
806:     playerHp: 68,
807:     playerMaxHp: 68,
808:     trainerName,
809:     trainerKey: trainerMeta?.key || null,
810:     log: trainerName
811:       ? `${trainerName} wants to battle! ${trainerName} sent out ${species.replace(/_/g, " ")} (Lv.${level})!`
812:       : `Wild ${species.replace(/_/g, " ")} (Lv.${level}) appeared in ${state.currentZone.displayName}!`,
813:     finished: false,
814:   };
815:   audio.playSfx("thunder");
816:   renderBattleModal();
817: }
