        except Exception:
            time.sleep(0.1)
    subprocess.run(["playwright-cli", "open", "http://127.0.0.1:8765/index.html"], check=True)
    subprocess.run(["playwright-cli", "resize", "1280", "720"], check=True)
    # Trigger a trainer battle with Pewter Gym Leader Brock and open the FIGHT submenu (MoveSelectionMenu + PrintMenuItem)
    subprocess.run(["playwright-cli", "eval", """() => {
      const pewterGym = window.POKEYELLOW.loadZone("PEWTER_GYM");
      const brock = window.POKEYELLOW.state.npcs[0];
      window.POKEYELLOW.triggerWildEncounter([12, "ONIX"], {
        trainerName: "BROCK",
        trainerClass: "OPP_BROCK",
        trainerSprite: "BROCK",
        party: [[10, "GEODUDE"], [12, "ONIX"]],
        endBattleText: "As proof of your victory, here is the BOULDERBADGE!"
      });
      // Open FIGHT submenu (MoveSelectionMenu + TYPE/PP box)
